import{a as i,j as e,L as a}from"./index-1nNoPf6f.js";import{C as s}from"./chevron-left-D24oSDKc.js";import{c as o}from"./createLucideIcon-CuJAIYJY.js";const l=o("Scale",[["path",{d:"m16 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z",key:"7g6ntu"}],["path",{d:"m2 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z",key:"ijws7r"}],["path",{d:"M7 21h10",key:"1b0cd5"}],["path",{d:"M12 3v18",key:"108xh3"}],["path",{d:"M3 7h2c2 0 5-1 7-2 2 1 5 2 7 2h2",key:"3gwbw2"}]]),d=[["1. Introduction and Acceptance","These Terms form a legally binding agreement between you and the Bago entity identified below. By creating an account or using the sendwithbago.com website, mobile app, APIs or services, you accept these Terms, our Privacy Policy and referenced policies. If acting for an organisation, you confirm that you may bind it."],["2. Definitions","BAGO Ltd is incorporated in England and Wales. Send With Bago Enterprise is incorporated in Nigeria and is a subsidiary of BAGO Ltd. The Platform is Bago’s apps, website, APIs and services. A Sender lists a Shipment; a Traveller or Carrier offers to transport it; KYC means identity verification; Escrow means the safeguarded payment flow."],["3. Your Contracting Entity","Users registered, resident or habitually located in Nigeria contract with Send With Bago Enterprise. Users in the United Kingdom and every other country contract with BAGO Ltd. On cross-entity routes, each User contracts only with their own entity, while carriage remains a direct contract between Sender and Traveller."],["4. Marketplace, Not a Carrier","Bago provides technology connecting Senders and Travellers. It is not a courier, freight forwarder, customs broker, carrier, logistics company or postal operator and does not transport, inspect or take custody of Shipments. No partnership, agency, employment, fiduciary or joint-venture relationship is created."],["5. Eligibility, Registration and KYC","You must be at least 18, legally able to contract, permitted to use the Platform and complete KYC when required. Information must remain accurate. Bago may suspend accounts for failed KYC, fraud, identity mismatch or sanctions exposure. You are responsible for account security and activity."],["6. Prohibited Items and Legal Compliance","You must not list, accept or transport illegal drugs; weapons, firearms, ammunition or explosives; counterfeit, pirated or stolen goods; unlawfully carried currency; human remains or body parts; unlawfully traded wildlife; hazardous, flammable, toxic or radioactive materials; sanctioned or otherwise unlawful goods; or items connected to trafficking, smuggling or exploitation. Every Shipment must satisfy origin, transit, destination, customs and airline rules. Bago may request information, remove listings and report suspected illegality."],["7. Sender Obligations","A Sender warrants lawful ownership or authority, accurate contents, weight, dimensions and value, all necessary permits, prescriptions and certificates, respect for third-party rights, and cooperation with inspection."],["8. Traveller Obligations","A Traveller must reasonably inspect Shipments, decline undisclosed, suspicious or unlawful contents, comply with customs and tax formalities, hold required travel authorisations and never facilitate smuggling or duty evasion. Travellers bear personal legal responsibility for Shipments they knowingly carry."],["9. Customs and Cross-Border Compliance","Users alone are responsible for customs declarations, duties, VAT, licences and quantity or value restrictions in every relevant jurisdiction, including UK, Nigerian and EU rules where applicable. Bago is not a customs broker or declarant."],["10. International Users and Trip Listings","Users must determine legality in every affected country. A Trip Listing describes independent travel plans; Bago does not arrange or guarantee travel and is not responsible for cancellation, delay, rerouting, visa refusal or denial of entry. Compliance screening reduces risk but is not legal clearance."],["11. Fees, Payments and Escrow","Fees are shown at booking. Payments and payout safeguards use third-party payment partners available for the transaction. Sender funds may be held pending delivery confirmation. Bago is not a bank or deposit-taking institution. Refunds follow the Refund and Cancellation Policy."],["12. Insurance","Optional cover may be offered through MyCover.ai or another insurance partner. The partner, not Bago, underwrites and administers the policy, limits, exclusions and claims."],["13. Open-Box Verification","A Traveller may request and a Sender may permit inspection before acceptance. A Traveller may decline when a reasonable request is refused. Bago does not supervise or guarantee inspection. Inspection, KYC and AI screening reduce risk but do not guarantee legality, accuracy or safety."],["14. User Disputes","Bago may offer an informal dispute mechanism but does not legally adjudicate carriage disputes. Claims concerning carriage, conduct or misrepresentation remain between Users, without limiting independent legal remedies."],["15. Limitation of Liability","To the maximum extent allowed by law, Bago is not liable for loss, theft, damage, delay, seizure, prohibited goods, government action, User conduct, travel disruption or insurance-partner decisions. Aggregate liability is limited to service fees received from that User during the three months before the event, except where law prohibits limitation."],["16. Indemnification","Each User indemnifies their contracting entity, the Group and personnel against claims, fines, losses and reasonable legal costs arising from that User’s breach, unlawful goods, violation of law, third-party dispute or Trip Listing. This survives termination."],["17. Disclaimer of Warranties","The Platform is provided “as is” and “as available”. Bago does not guarantee uninterrupted operation, User identity or conduct, or Shipment legality, safety or condition. Mandatory statutory rights are not excluded."],["18. Data Protection and Privacy","BAGO Ltd processes data under the UK GDPR and Data Protection Act 2018; Send With Bago Enterprise under the Nigeria Data Protection Act 2023. Data may be shared lawfully with KYC providers, payment processors, insurers and authorities. Appropriate mechanisms apply to cross-border transfers. See the Privacy Policy for full details."],["19. Intellectual Property","Platform software, branding and content, excluding User content, are owned by or licensed to BAGO Ltd. Users receive a limited, revocable, non-exclusive and non-transferable licence."],["20. Suspension and Termination","Bago may suspend or terminate accounts for breach, fraud, illegality, prohibited goods, failed KYC or risk to Users or the Platform. Users may close accounts subject to outstanding transactions and disputes."],["21. Force Majeure","Bago is not liable for delay or failure caused by events beyond reasonable control, including disasters, war, civil unrest, government action, strikes, network failures or pandemics."],["22. Governing Law and Disputes","BAGO Ltd Users are governed by England and Wales law and courts; Send With Bago Enterprise Users by Nigerian law and courts, subject to mandatory consumer rights. The parties may agree to negotiation and, if unresolved after 30 days, applicable arbitration in London or Lagos. Data-protection complaint rights remain unaffected."],["23. Miscellaneous","Invalid provisions are modified only as needed and the remainder survives. These Terms and referenced policies are the entire agreement. Material amendments will be notified at least 30 days before taking effect. Users may not assign without consent; Bago may assign during a transaction or Group restructuring. Failure to enforce is not a waiver."],["24. Contact","BAGO Ltd (United Kingdom) and Send With Bago Enterprise (Nigeria): send@sendwithbago.com"]];function p(){const r=i();return e.jsxs("div",{className:"min-h-screen bg-[#F8F6F3]",children:[e.jsxs("nav",{className:"sticky top-0 z-50 flex items-center justify-between border-b border-gray-100 bg-white px-6 py-3 md:px-12",children:[e.jsxs("button",{onClick:()=>r(-1),className:"flex items-center gap-1 text-xs font-bold text-[#012126]",children:[e.jsx(s,{size:20}),"Back"]}),e.jsx(a,{to:"/",children:e.jsx("img",{src:"/bago_logo.png",alt:"Bago",className:"h-8"})}),e.jsx("div",{className:"w-16"})]}),e.jsxs("main",{className:"mx-auto max-w-4xl px-6 py-12",children:[e.jsxs("header",{className:"mb-10 text-center",children:[e.jsx("h1",{className:"text-3xl font-black text-[#012126]",children:"Terms & Conditions"}),e.jsx("p",{className:"mt-3 text-[10px] font-bold uppercase tracking-[2px] text-gray-500",children:"Last updated: July 15, 2026"})]}),e.jsxs("div",{className:"rounded-[32px] border border-gray-100 bg-white p-8 shadow-sm md:p-12",children:[e.jsxs("div",{className:"mb-10 flex gap-3 rounded-2xl bg-[#5845D8]/5 p-5 text-sm leading-6 text-[#012126]",children:[e.jsx(l,{className:"mt-1 shrink-0 text-[#5845D8]",size:20}),e.jsx("p",{children:"Please read these Terms carefully. They govern use of the Bago marketplace and identify the entity you contract with based on your location."})]}),e.jsx("div",{className:"space-y-9",children:d.map(([t,n])=>e.jsxs("section",{children:[e.jsx("h2",{className:"mb-3 text-base font-black uppercase tracking-tight text-[#012126]",children:t}),e.jsx("p",{className:"text-sm font-medium leading-7 text-gray-600",children:n})]},t))}),e.jsxs("p",{className:"mt-12 border-t border-gray-100 pt-8 text-center text-xs font-bold text-gray-500",children:["Questions? ",e.jsx(a,{to:"/help",className:"text-[#5845D8] underline",children:"Visit the Help Centre"})]})]})]})]})}export{p as default};
